using System;
using System.IO;
using System.Windows.Forms;
using System.Diagnostics;
using System.Runtime.InteropServices;

namespace BreakReminderInstaller
{
    class Program
    {
        [STAThread]
        static void Main()
        {
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            
            DialogResult dr = MessageBox.Show(
                "Do you want to install Break Reminder on this computer?\n\nIt will be installed to your local profile and added to the Start Menu.",
                "Break Reminder Setup", MessageBoxButtons.YesNo, MessageBoxIcon.Question);
            if (dr != DialogResult.Yes) return;
            
            try
            {
                string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
                string installDir = Path.Combine(localAppData, "BreakReminder");
                
                if (!Directory.Exists(installDir))
                {
                    Directory.CreateDirectory(installDir);
                }
                
                string exePath = Path.Combine(installDir, "BreakReminder.exe");
                
                string b64 = "";
                
                byte[] exeBytes = Convert.FromBase64String(b64);
                
                // Kill if running
                foreach (var process in Process.GetProcessesByName("BreakReminder"))
                {
                    try { process.Kill(); process.WaitForExit(2000); } catch { }
                }
                
                System.IO.File.WriteAllBytes(exePath, exeBytes);
                
                // Create Shortcut using COM
                string startMenu = Environment.GetFolderPath(Environment.SpecialFolder.Programs);
                string shortcutPath = Path.Combine(startMenu, "Break Reminder.lnk");
                
                CreateShortcut(shortcutPath, exePath, "Reminds you to take a break");
                
                // Set Auto Start using Registry
                using (Microsoft.Win32.RegistryKey key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run", true))
                {
                    key.SetValue("BreakReminder", exePath);
                }
                
                MessageBox.Show("Installation complete! Break Reminder is now running and will auto-start with Windows.", "Setup Complete", MessageBoxButtons.OK, MessageBoxIcon.Information);
                
                Process.Start(new ProcessStartInfo()
                {
                    FileName = exePath,
                    UseShellExecute = true
                });
            }
            catch (Exception ex)
            {
                MessageBox.Show("Installation failed:\n" + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
        
        static void CreateShortcut(string shortcutPath, string targetPath, string description)
        {
            try
            {
                Type t = Type.GetTypeFromProgID("WScript.Shell");
                dynamic shell = Activator.CreateInstance(t);
                var shortcut = shell.CreateShortcut(shortcutPath);
                shortcut.TargetPath = targetPath;
                shortcut.WorkingDirectory = Path.GetDirectoryName(targetPath);
                shortcut.Description = description;
                shortcut.IconLocation = targetPath + ",0";
                shortcut.Save();
            }
            catch {}
        }
    }
}
